private enum Page{Home,Play,Heroes,Shop,Profile,Settings}private static MainMenuController instance;private Page page;private bool visible=true,launching;private GUIStyle title,subtitle,button,primary,small,panel,heroName,sideLabel;private Texture2D dimTexture,zeroTexture,lumenTexture,whiteTexture;private int selectedHero;private float openedAt,launchAt;private string profileName;private readonly string[] roles={"ASSASSIN","TANK","MARKSMAN","MAGE","SUPPORT","BRUISER"};
[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void AutoCreate(){if(FindAnyObjectByType<MainMenuController>()==null)new GameObject("DF_MainMenu").AddComponent<MainMenuController>();}private void Awake(){if(instance!=null&&instance!=this){Destroy(gameObject);return;}instance=this;selectedHero=(int)PlayerHeroSelection.Selected;profileName=PlayerProfile.PlayerName;openedAt=Time.unscaledTime;Time.timeScale=0;dimTexture=MakeTexture(StylizedArtDirection.Ink);zeroTexture=MakeTexture(StylizedArtDirection.ZeroDark);lumenTexture=MakeTexture(StylizedArtDirection.LumenDark);whiteTexture=MakeTexture(Color.white);}private void Update(){if(launching&&Time.unscaledTime-launchAt>.62f)EnterMatch();}
private Texture2D MakeTexture(Color c){Texture2D t=new Texture2D(1,1);t.SetPixel(0,0,c);t.Apply();return t;}private void OnDestroy(){if(instance==this)instance=null;DestroyTexture(dimTexture);DestroyTexture(zeroTexture);DestroyTexture(lumenTexture);DestroyTexture(whiteTexture);}private static void DestroyTexture(Texture2D t){if(t!=null)Destroy(t);}private void OnGUI(){if(!visible)return;EnsureStyles();DrawBackground();if(launching){DrawLaunch();return;}switch(page){case Page.Play:DrawPlay();break;case Page.Heroes:DrawHeroes();break;case Page.Shop:DrawShop();break;case Page.Profile:DrawProfile();break;case Page.Settings:DrawSettings();break;default:DrawHome();break;}}
private string HeroName(int index){return HeroIdentity.NameFor((HeroId)index).ToUpperInvariant();}
private void DrawBackground(){GUI.DrawTexture(new Rect(0,0,Screen.width,Screen.height),dimTexture);float t=Time.unscaledTime-openedAt,pulse=.5f+.5f*Mathf.Sin(t*1.35f),collision=Mathf.Sin(t*.7f)*Screen.width*.006f;GUI.color=Color.white;GUI.DrawTexture(new Rect(0,0,Screen.width*.505f+collision,Screen.height),zeroTexture);GUI.DrawTexture(new Rect(Screen.width*.495f+collision,0,Screen.width*.505f,Screen.height),lumenTexture);float center=Screen.width*.5f+collision;for(int i=0;i<12;i++){float phase=t*(.55f+i*.025f)+i*1.37f,y=(i+.4f)*Screen.height/12f+Mathf.Sin(phase*1.7f)*15,x=center+Mathf.Sin(phase)*14;GUI.color=i%2==0?new Color(StylizedArtDirection.ZeroEnergy.r,StylizedArtDirection.ZeroEnergy.g,StylizedArtDirection.ZeroEnergy.b,.25f+.2f*pulse):new Color(StylizedArtDirection.LumenEnergy.r,StylizedArtDirection.LumenEnergy.g,StylizedArtDirection.LumenEnergy.b,.25f+.2f*pulse);GUI.DrawTexture(new Rect(x-2,y-18,4,36),whiteTexture);}GUI.color=Color.white;GUI.DrawTexture(new Rect(center-(3+5*pulse)*.5f,0,3+5*pulse,Screen.height),whiteTexture);DrawComicCuts(center,t);GUI.Label(new Rect(18,Screen.height*.48f,Screen.width*.22f,32),"DIMENSION ZERO",sideLabel);GUI.Label(new Rect(Screen.width*.78f-18,Screen.height*.48f,Screen.width*.22f,32),"LUMEN",sideLabel);}
private void DrawComicCuts(float center,float t){for(int i=0;i<5;i++){float y=Screen.height*(.13f+i*.18f),drift=Mathf.Sin(t*.45f+i)*8;GUI.color=new Color(1,1,1,.07f);GUI.DrawTexture(new Rect(0,y+drift,center*.7f,2),whiteTexture);GUI.DrawTexture(new Rect(center+center*.3f,y-drift,Screen.width-(center+center*.3f),2),whiteTexture);}GUI.color=Color.white;}
private void DrawHome(){float w=Mathf.Min(720,Screen.width*.9f),x=(Screen.width-w)*.5f,top=Screen.height*.07f;GUI.Label(new Rect(x,top,w,82),"DIMENSIONS FRONT",title);GUI.Label(new Rect(x,top+72,w,30),FounderEntitlement.Owned?"◆ FIRST TRAVELER ◆":"FIGHT FOR YOUR REALITY",subtitle);float cardW=Mathf.Min(170,Screen.width*.2f),cardH=Mathf.Min(215,Screen.height*.27f);StylizedHeroCard.Draw(new Rect(Screen.width*.5f-cardW*.5f,top+108,cardW,cardH),(HeroId)selectedHero,whiteTexture,Time.unscaledTime);GUI.Label(new Rect(x,top+108+cardH,w,25),$"{HeroName(selectedHero)}  •  {roles[selectedHero]}",small);float bw=Mathf.Min(390,w*.72f),bx=(Screen.width-bw)*.5f,by=Mathf.Max(top+cardH+148,Screen.height*.55f);Rect action=new Rect(bx-14,by-10,bw+28,264);DimensionUiMotif.DrawSplitPanel(action,whiteTexture,StylizedArtDirection.ZeroEnergy,StylizedArtDirection.LumenEnergy,Time.unscaledTime);if(GUI.Button(new Rect(bx,by,bw,62),"PLAY",primary))page=Page.Play;if(GUI.Button(new Rect(bx,by+72,bw,42),"HEROES",button))page=Page.Heroes;if(GUI.Button(new Rect(bx,by+120,bw,42),FounderEntitlement.Owned?"SHOP  •  FOUNDER OWNED":"SHOP  •  FOUNDERS PACK",button))page=Page.Shop;if(GUI.Button(new Rect(bx,by+168,bw,42),$"PROFILE  •  {PlayerProfile.PlayerName}",button))page=Page.Profile;if(GUI.Button(new Rect(bx,by+216,bw,38),"SETTINGS",button))page=Page.Settings;GUI.Label(new Rect(x,Screen.height-30,w,20),"TWO REALITIES. ONE FRONT.",small);}
private void DrawPlay(){float w=Mathf.Min(650,Screen.width*.88f),x=(Screen.width-w)*.5f,y=Screen.height*.2f;GUI.Label(new Rect(x,Screen.height*.07f,w,62),"ENTER THE FRONT",title);Rect r=new Rect(x,y,w,310);DimensionUiMotif.DrawSplitPanel(r,whiteTexture,StylizedArtDirection.ZeroEnergy,StylizedArtDirection.LumenEnergy,Time.unscaledTime);GUI.Label(new Rect(x+30,y+20,w-60,30),"SELECT MATCH TYPE",subtitle);if(GUI.Button(new Rect(x+w*.16f,y+72,w*.68f,72),"AI MATCH\n5v5 • LOCAL",primary))BeginLaunch();GUI.enabled=false;GUI.Button(new Rect(x+w*.16f,y+166,w*.68f,72),"MULTIPLAYER\nCOMING SOON",primary);GUI.enabled=true;string status=MultiplayerGate.Instance!=null?MultiplayerGate.Instance.Status:"ONLINE FOUNDATION READY";GUI.Label(new Rect(x+30,y+246,w-60,28),status,small);if(GUI.Button(new Rect(x,y+332,180,46),"BACK",button))page=Page.Home;}
private void DrawHeroes(){float w=Mathf.Min(760,Screen.width*.9f),x=(Screen.width-w)*.5f,y=Screen.height*.22f;GUI.Label(new Rect(x,Screen.height*.07f,w,62),"CHOOSE YOUR HERO",title);Rect heroPanel=new Rect(x,y,w,300);DimensionUiMotif.DrawSplitPanel(heroPanel,whiteTexture,StylizedArtDirection.ZeroEnergy,StylizedArtDirection.LumenEnergy,Time.unscaledTime);StylizedHeroCard.Draw(new Rect(x+(w-Mathf.Min(210,w*.32f))*.5f,y+20,Mathf.Min(210,w*.32f),205),(HeroId)selectedHero,whiteTexture,Time.unscaledTime);if(GUI.Button(new Rect(x+18,y+95,55,55),"‹",button))ChangeHero(-1);if(GUI.Button(new Rect(x+w-73,y+95,55,55),"›",button))ChangeHero(1);GUI.Label(new Rect(x+70,y+222,w-140,42),HeroName(selectedHero),heroName);GUI.Label(new Rect(x+70,y+260,w-140,30),$"{roles[selectedHero]}   •   {selectedHero+1}/6",subtitle);if(GUI.Button(new Rect(x,y+322,180,46),"BACK",button))page=Page.Home;}
private void DrawShop(){float w=Mathf.Min(720,Screen.width*.9f),x=(Screen.width-w)*.5f,y=Screen.height*.12f;GUI.Label(new Rect(x,Screen.height*.035f,w,62),"SUPPORT DIMENSIONS FRONT",title);Rect shopPanel=new Rect(x,y,w,Screen.height*.68f);DimensionUiMotif.DrawSplitPanel(shopPanel,whiteTexture,StylizedArtDirection.ZeroEnergy,StylizedArtDirection.LumenEnergy,Time.unscaledTime);GUI.Label(new Rect(x+25,y+18,w-50,38),"FOUNDERS PACK  •  FIRST FRACTURE",heroName);GUI.Label(new Rect(x+30,y+60,w-60,28),FounderEntitlement.Owned?"THANK YOU, FIRST TRAVELER":"EARLY SUPPORTER EDITION",subtitle);float cy=y+100;for(int i=0;i<FounderPackCatalog.Rewards.Length;i++){string state=FounderEntitlement.Owned?"◆":"◇";GUI.Label(new Rect(x+55,cy+i*36,w-110,30),state+"  "+FounderPackCatalog.Rewards[i],small);}GUI.Label(new Rect(x+35,cy+230,w-70,28),FounderEntitlement.Owned?"FOUNDER STATUS: OWNED":"ONE-TIME PACK  •  "+FounderPackCatalog.TargetPrice,subtitle);GUI.enabled=!FounderEntitlement.Owned;GUI.Button(new Rect(x+w*.22f,cy+270,w*.56f,54),FounderEntitlement.Owned?"OWNED":"PURCHASE • STORE BILLING REQUIRED",primary);GUI.enabled=true;GUI.Label(new Rect(x+35,cy+332,w-70,24),FounderEntitlement.Owned?"First Fracture cosmetics active.":"Cosmetic only. No gameplay advantage.",small);if(GUI.Button(new Rect(x,y+Screen.height*.7f,180,44),"BACK",button))page=Page.Home;}
private void ChangeHero(int direction){selectedHero=(selectedHero+direction+6)%6;PlayerHeroSelection.Select((HeroId)selectedHero);}private void DrawProfile(){float w=Mathf.Min(620,Screen.width*.86f),x=(Screen.width-w)*.5f,y=Screen.height*.17f;GUI.Label(new Rect(x,Screen.height*.055f,w,62),"PLAYER PROFILE",title);Rect profilePanel=new Rect(x,y,w,340);DimensionUiMotif.DrawSplitPanel(profilePanel,whiteTexture,StylizedArtDirection.ZeroEnergy,StylizedArtDirection.LumenEnergy,Time.unscaledTime);GUI.Label(new Rect(x+30,y+18,w-60,26),PlayerProfile.HasFounderFrame?"◆ FIRST FRACTURE PROFILE ◆":"DIMENSIONS FRONT PROFILE",subtitle);GUI.Label(new Rect(x+30,y+48,w-60,24),PlayerProfile.DisplayTitle,small);GUI.Label(new Rect(x+30,y+82,w-60,28),"DISPLAY NAME",subtitle);profileName=GUI.TextField(new Rect(x+80,y+116,w-160,42),profileName,16);GUI.Label(new Rect(x+30,y+170,w-60,28),"AVATAR",subtitle);int avatarCount=FounderEntitlement.Owned?7:6,totalWidth=avatarCount*52;float ax=x+(w-totalWidth)*.5f;for(int i=0;i<avatarCount;i++){bool chosen=PlayerProfile.Avatar==i;string label=i==6?"◆":(i+1).ToString();GUI.enabled=!chosen;if(GUI.Button(new Rect(ax+i*52,y+208,44,44),label,chosen?primary:button))PlayerProfile.Avatar=i;GUI.enabled=true;}GUI.Label(new Rect(x+30,y+267,w-60,25),FounderEntitlement.Owned?"Founder avatar unlocked • permanent account cosmetic":"Built-in Dimensions Front avatars",small);if(GUI.Button(new Rect(x,y+362,180,46),"BACK",button)){PlayerProfile.PlayerName=profileName;profileName=PlayerProfile.PlayerName;page=Page.Home;}}
private void DrawSettings(){float w=Mathf.Min(620,Screen.width*.86f),x=(Screen.width-w)*.5f,y=Screen.height*.18f;GUI.Label(new Rect(x,Screen.height*.07f,w,62),"SETTINGS",title);Rect settingsPanel=new Rect(x,y,w,330);DimensionUiMotif.DrawSplitPanel(settingsPanel,whiteTexture,StylizedArtDirection.ZeroEnergy,StylizedArtDirection.LumenEnergy,Time.unscaledTime);DrawVolume(x,y+35,w,"MASTER VOLUME",PlayerProfile.MasterVolume,v=>PlayerProfile.MasterVolume=v);DrawVolume(x,y+105,w,"MUSIC",PlayerProfile.MusicVolume,v=>PlayerProfile.MusicVolume=v);DrawVolume(x,y+175,w,"SFX",PlayerProfile.SfxVolume,v=>PlayerProfile.SfxVolume=v);GUI.Label(new Rect(x+30,y+245,w-60,28),"LANGUAGE  •  ENGLISH",subtitle);GUI.Label(new Rect(x+30,y+278,w-60,22),"More languages will be added later.",small);if(GUI.Button(new Rect(x,y+352,180,46),"BACK",button))page=Page.Home;}private void DrawVolume(float x,float y,float w,string name,float value,System.Action<float> set){GUI.Label(new Rect(x+30,y,w-60,24),$"{name}  {Mathf.RoundToInt(value*100)}%",small);float next=GUI.HorizontalSlider(new Rect(x+75,y+31,w-150,22),value,0,1);if(!Mathf.Approximately(next,value))set(next);}
private void BeginLaunch(){PlayerHeroSelection.Select((HeroId)selectedHero);launching=true;launchAt=Time.unscaledTime;}private void DrawLaunch(){float p=Mathf.Clamp01((Time.unscaledTime-launchAt)/.62f),ease=p*p*(3-2*p),w=Mathf.Lerp(Screen.width*.02f,Screen.width*.72f,ease);GUI.color=new Color(1,1,1,.12f+.65f*ease);GUI.DrawTexture(new Rect(Screen.width*.5f-w*.5f,0,w,Screen.height),whiteTexture);GUI.color=Color.white;GUI.Label(new Rect(0,Screen.height*.43f,Screen.width,70),p>.48f?"ENTER THE FRONT":"REALITY COLLISION",heroName);}private void EnterMatch(){visible=false;Time.timeScale=1;gameObject.SetActive(false);}
private void EnsureStyles(){if(title!=null)return;title=new GUIStyle(GUI.skin.label){fontSize=Mathf.Clamp(Screen.width/18,34,66),fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};subtitle=new GUIStyle(GUI.skin.label){fontSize=Mathf.Clamp(Screen.width/48,15,23),fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};button=new GUIStyle(GUI.skin.button){fontSize=Mathf.Clamp(Screen.width/48,15,22),fontStyle=FontStyle.Bold};primary=new GUIStyle(button){fontSize=Mathf.Clamp(Screen.width/38,20,29)};small=new GUIStyle(GUI.skin.label){fontSize=13,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};panel=new GUIStyle(GUI.skin.box);heroName=new GUIStyle(title){fontSize=Mathf.Clamp(Screen.width/24,27,46)};sideLabel=new GUIStyle(small){fontSize=12,alignment=TextAnchor.MiddleCenter};}
